	mcast_socket = nl_socket_alloc();
	genl_connect(mcast_socket);
	driver_id = genl_ctrl_resolve(mcast_socket, "nbd");
	ret = nl_socket_add_membership(mcast_socket,
		genl_ctrl_resolve_grp(mcast_socket, NBD_GENL_FAMILY_NAME, NBD_GENL_MCAST_GROUP_NAME));
	nl_socket_modify_cb(mcast_socket, NL_CB_VALID, NL_CB_CUSTOM, persist_callback, &state);

	while (!quit) {
		if (state.link_dead) {
			state.link_dead = 0;
			reconnect & reconfigure with backoff;
			continue;
