+		/* Check if all connections were successful */
+		int all_success = 1;
+		for (i = 0; i < cur_client->nconn; i++) {
+			if (new_sockfds[i] < 0) {
+				all_success = 0;
+				break;
+			}
+		}
+
+		if (all_success) {
+			fprintf(stderr, "Successfully reconnected after %d attempts\n", attempt + 1);
+			return 0;
+		}
+
+		/* Exponential backoff */
+		backoff_time *= 2;
+		attempt++;
