void nbdtab_set_property(char *property, char *val) {
	if(found_config) return;
	SET_PROP("port", port, val);
	SET_PROP("certfile", cert, val);
	SET_PROP("keyfile", key, val);
	SET_PROP("cacertfile", cacert, val);
