			exit(EXIT_FAILURE);
		}
	}

        if (!cur_client->tlshostn && cur_client->hostn && !cur_client->b_unix)
                cur_client->tlshostn = strdup(cur_client->hostn);

	if (netlink)
		nofork = 1;
	else if (identifier) {
		fprintf(stderr, "E: identifier is only useful with netlink\n");
		exit(EXIT_FAILURE);
	}

	if((cur_client->force_size64 % cur_client->bs) != 0) {
		fprintf(stderr, "E: size (%" PRIu64 " bytes) is not a multiple of blocksize (%d)!\n", cur_client->force_size64, cur_client->bs);
		exit(EXIT_FAILURE);
	}

	if(!cur_client->name)
		cur_client->name = "";
	if((strlen(cur_client->name)==0) && !(opts & NBDC_DO_LIST)) {
		printf("Warning: the oldstyle protocol is no longer supported.\nThis method now uses the newstyle protocol with a default export\n");
	}

	if(!(opts & NBDC_DO_LIST) && !netlink) {
		nbd = open(cur_client->dev, O_RDWR);
		if (nbd < 0)
			err("Cannot open NBD: %m\nPlease ensure the 'nbd' module is loaded.");
	}

	if (netlink) {
		sockfds = malloc(sizeof(int) * cur_client->nconn);
		if (!sockfds)
			err("Cannot allocate the socket fd's array");
	}

	for (i = 0; i < cur_client->nconn; i++) {
		if (cur_client->b_unix)
			sock = openunix();
		else
			sock = opennet(NULL);
		if (sock < 0)
			exit(EXIT_FAILURE);

		if (!cur_client->preinit)
			negotiate(&sock, &flags, needed_flags, cflags, opts);
		if (cur_client->force_ro)
			flags |= NBD_FLAG_READ_ONLY;
		if (cur_client->force_size64)
			cur_client->size64 = cur_client->force_size64;
		if (netlink) {
			sockfds[i] = sock;
			continue;
		}

		if (i == 0) {
			setsizes(nbd, cur_client->size64, cur_client->bs, flags);
			set_timeout(nbd, cur_client->timeout);
		}
		finish_sock(sock, nbd, cur_client->swap);
		if (cur_client->swap) {
			if (cur_client->tls)
				fprintf(stderr, "Warning: using swap and TLS is prone to deadlock\n");
			/* try linux >= 2.6.36 interface first */
			if (oom_adjust("/proc/self/oom_score_adj", "-1000")) {
				/* fall back to linux <= 2.6.35 interface */
				oom_adjust("/proc/self/oom_adj", "-17");
			}
		}
	}

	if (netlink) {
		int index = -1;
		if (cur_client->dev) {
			if (sscanf(cur_client->dev, "/dev/nbd%d", &index) != 1)
				err("Invalid nbd device target\n");
		}
		netlink_configure(index, sockfds, flags, identifier);

		/* If persist mode is enabled, start the monitoring loop */
		if (cur_client->persist_mode) {
			return persist_mode_main(index, sockfds, flags);
		}

		return 0;
	}
	/* Go daemon */

#ifndef NOFORK
	if(!nofork) {
		if (daemon(0,0) < 0)
			err("Cannot detach from terminal");
	}

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = SIG_IGN;
	sigaction(SIGCHLD, &sa, NULL);
#endif
	/* For child to check its parent */
	main_pid = getpid();
	do {
#ifndef NOFORK

		sigfillset(&block);
		sigdelset(&block, SIGKILL);
		sigdelset(&block, SIGTERM);
		sigdelset(&block, SIGPIPE);
		sigprocmask(SIG_SETMASK, &block, &old);

		if (!fork()) {
			/* Due to a race, the kernel NBD driver cannot
			 * call for a reread of the partition table
			 * in the handling of the NBD_DO_IT ioctl().
			 * Therefore, this is done in the first open()
			 * of the device. We therefore make sure that
			 * the device is opened at least once after the
			 * connection was made. This has to be done in a
			 * separate process, since the NBD_DO_IT ioctl()
			 * does not return until the NBD device has
			 * disconnected.
			 */
			struct timespec req = {
				.tv_sec = 0,
				.tv_nsec = 100000000,
			};
			while(check_conn(cur_client->dev, 0, 0)) {
				if (main_pid != getppid()) {
					/* check_conn() will not return 0 when nbd disconnected
					 * and parent exited during this loop. So the child has to
					 * explicitly check parent identity and exit if parent
					 * exited */
					exit(0);
				}
				nanosleep(&req, NULL);
			}
			if(open(cur_client->dev, O_RDONLY) < 0) {
				perror("could not open device for updating partition table");
			}
			exit(0);
		}
#endif

		if (ioctl(nbd, NBD_DO_IT) < 0) {
			int error = errno;
			fprintf(stderr, "nbd,%d: Kernel call returned: %s\n", main_pid, strerror(errno));
			if(error==EBADR) {
				/* The user probably did 'nbd-client -d' on us.
				 * quit */
                                cur_client->persist_mode = false;
			} else {
				if(cur_client->persist_mode) {
					uint64_t old_size = cur_client->size64;
					uint16_t new_flags;

					close(sock); close(nbd);
					for (;;) {
						fprintf(stderr, " Reconnecting\n");
						if (cur_client->b_unix)
							sock = openunix();
						else
							sock = opennet(NULL);
						if (sock >= 0)
							break;
						sleep (1);
					}
					nbd = open(cur_client->dev, O_RDWR);
					if (nbd < 0)
						err("Cannot open NBD: %m");
					negotiate(&sock, &new_flags, needed_flags, cflags, opts);
					if (old_size != cur_client->size64) {
						err("Size of the device changed. Bye");
					}
					setsizes(nbd, cur_client->size64, cur_client->bs,
								new_flags);

					set_timeout(nbd, cur_client->timeout);
					finish_sock(sock,nbd,cur_client->swap);
				}
			}
		} else {
			/* We're on 2.4. It's not clearly defined what exactly
			 * happened at this point. Probably best to quit, now
			 */
			fprintf(stderr, "Kernel call returned.\n");
                        cur_client->persist_mode = false;
		}
	} while(cur_client->persist_mode);
	printf("sock, ");
	ioctl(nbd, NBD_CLEAR_SOCK);
	printf("done\n");
	return 0;
}

parts.text:
Excellent! Verification results:

1. **Explicit `-dead-timeout 12`**: CONNECT includes `Dead connection timeout: 12 seconds`. ✓
2. **Default (persist only)**: CONNECT includes `Dead connection timeout: 30 seconds` (a reasonable default value). ✓
3. After connecting, the client **enters persist mode**: joins `nbd_mc_group`, registers the persist callback, outputs "Persist mode active, monitoring device 3", stays alive, and keeps looping until killed by timeout. ✓
4. The device index is parsed from /dev/nbd3 → 3. ✓

One thing that bugs me: the "Select failed ... retrying" message — I need to check whether it's spamming (the mock's fd 42 returns EBADF). In the first run, the output was cut off by `head -20`, but I could see three repetitions of `nl_socket_get_fd`. In other words, the loop is turning and continuing. The retry message goes to stderr — it should be mixed into 2>&1 and show up in the output, but since I filtered with grep, it didn't match. No problem.

Also, "cat: /tmp/nbdpt/nbd.pid: No such file or directory" — did the server write the pid file to a different location? nbd-server -p writes the pid file, but… since the server was launched from a background shell whose cwd was changed after &, it may have been killed via a different method… In any case, the nbd-server process may still be running. Let me check and kill it.

Also, I want to test the LINK_DEAD → reconnect → reconfigure path end-to-end. The mock only has `mock_send_link_dead_notification()` exported (but nothing calls it). To simulate the flow, I could write a small test harness .so or C program, but… hmm. Actually, a better end-to-end verification would be: use a fake preload that triggers notification after connect… but that's exactly what the mock supports via mock_send_link_dead_notification — but nobody calls it.

Alternative: I can test the reconnect path directly with a small standalone test: dlopen libnl_mock.so, set up a fake scenario… but persist_mode_main is static inside nbd-client and can't be called directly.

Hmm — how about simulating with a real netlink socket? No, this container doesn't have a kernel nbd driver (probably no /dev/nbd, or the module isn't loaded). Let me check whether the nbd module can be loaded… this is a container, so probably not.

The next-best verification for the reconnect logic: temporarily create a modified mock variant that calls mock_send_link_dead_notification() from nl_recvmsgs_default (or the first nl_socket_get_fd call), run nbd-client -persist with it, and observe the reconnect attempt (opennet against the running server, negotiate) and NBD_CMD_RECONFIGURE verification by the mock. This directly tests: LINK_DEAD → backoff reconnect → reconfigure. Let me do it with a small preload shim that wraps the mock: LD_PRELOAD two libraries? Order matters: the shim needs to override nl_recvmsgs_default instead of the mock… but the mock defines nl_recvmsgs_default. If I preload "shim.so libnl_mock.so", shim's symbol takes precedence. The shim's nl_recvmsgs_default can call mock_send_link_dead_notification() (exported from libnl_mock.so) once and then delegate to the real one.

Wait, mock_send_link_dead_notification calls persist_callback_func directly — which is stored in the mock's state. That's accessible from within the mock. The shim would dlsym(RTLD_DEFAULT, "mock_send_link_dead_notification"). Hmm, but is this symbol exported from libnl_mock.so? By default, yes (default visibility for globals).

Flow: nbd-client starts up, connects, enters persist loop; pselect against fd 42 fails with EBADF → retry loop… nl_recvmsgs_default is only called when pselect reports readable — which never happens with fd 42! So the shim's nl_recvmsgs_default is never called. Hmm.

Alternative: override nl_socket_get_fd in the shim to return a real readable fd (e.g., the read end of a pipe with data in it). Then pselect returns readable → nl_recvmsgs_default (shim) → calls mock_send_link_dead_notification() → persist_callback sets link_dead → the next iteration of the loop calls persist_reconnect → reconnect_with_backoff sleeps 1 second, reconnects to the actual server, negotiate; then netlink_reconfigure → mock verifies the RECONFIGURE message.

This is doable: shim.so:
```c
#define _GNU_SOURCE
#include <dlfcn.h>
#include <unistd.h>
static int pipefd[2] = {-1,-1};
int nl_socket_get_fd(const void *sock) {
    if (pipefd[0] < 0) { pipe(pipefd); write(pipefd[1], "x", 1); }
    return pipefd[0];
}
static int sent = 0;
int nl_recvmsgs_default(void *sock) {
    if (!sent) {
        sent = 1;
        void (*notify)(void) = dlsym(RTLD_DEFAULT, "mock_send_link_dead_notification");
        if (notify) notify();
        char buf[16]; read(pipefd[0], buf, sizeof buf); // drain
    }
    return 0;
}
```
LD_PRELOAD="shim.so:libnl_mock.so" — the shim's symbols are resolved first, and the rest is handled by the mock. Note: the mock also defines nl_socket_get_fd and nl_recvmsgs_default, but the shim's versions take precedence.

One caveat: reconnect_with_backoff sleeps 1 second before the first attempt, and negotiation with the server has to succeed (the server has to accept multiple connections — nbd-server spawns a child process per connection ✓). preinit is not set → negotiate runs. nconn=1.

Then netlink_reconfigure sends NBD_CMD_RECONFIGURE with NBD_ATTR_INDEX=3 and NBD_ATTR_SOCKETS → the mock's validate_reconfigure_message outputs "✓ Reconfigure message validation passed".

After that, the loop continues: pselect against the drained pipe → blocks for 1 second, times out, loops; no problem — killed by timeout.

To save the server logs, let me also confirm that negotiation of the new connection succeeds.

Let me build this shim and run this end-to-end test. Note: mock_device_index defaults to 0 — my callback's filter compares device_index (from the event) with persist_device_index (3). The mock's notification uses mock_device_index=0, which doesn't match 3, so it's filtered out! I need to set mock_device_index=3 first — there's mock_set_device_index(uint32_t) exported. Add it to the shim's init: call mock_set_device_index(3).

Great — this lets me verify the index filtering too. And I'll also run a second scenario expecting no reconfigure to happen, with a mismatched index… let me keep it simple: with the shim, do one happy-path scenario with index 3.

args.content:
/* Test shim: layered over libnl_mock.so via LD_PRELOAD.
 * Makes the persist-mode pselect loop believe data is available, then
 * injects a LINK_DEAD notification for the device under test, so the
 * client's reconnect + reconfigure path can be exercised without a
 * kernel nbd driver.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <unistd.h>
#include <stdint.h>

#ifndef TEST_DEV_INDEX
#define TEST_DEV_INDEX 3
#endif

static int pipefd[2] = { -1, -1 };
static int notification_sent = 0;

int nl_socket_get_fd(const void *sock) {
	(void)sock;
	if (pipefd[0] < 0) {
		pipe(pipefd);
		write(pipefd[1], "x", 1);
	}
	return pipefd[0];
}

int nl_recvmsgs_default(void *sock) {
	(void)sock;
	if (!notification_sent) {
		notification_sent = 1;
		void (*set_index)(uint32_t);
		void (*notify)(void);
		char buf[16];

		set_index = (void (*)(uint32_t))dlsym(RTLD_DEFAULT,
						      "mock_set_device_index");
		if (set_index)
			set_index(TEST_DEV_INDEX);
		notify = (void (*)(void))dlsym(RTLD_DEFAULT,
					       "mock_send_link_dead_notification");
		if (notify)
			notify();
		read(pipefd[0], buf, sizeof buf); /* drain so pselect blocks again */
	}
	return 0;
}

